/**
 * * `draft` - draft
 * * `pending` - pending
 * * `in_progress` - in_progress
 * * `to_be_audited` - to_be_audited
 * * `in_human_review` - in_human_review
 * * `completed` - completed
 */
export type StateEnum = 'draft' | 'pending' | 'in_progress' | 'to_be_audited' | 'in_human_review' | 'completed';

/**
 * GET representation of a task — Section 7.2 fields, in plan order.
 */
export type Task = {
    /**
     * {PID}-T{index} (Section 7.3); server-assigned, immutable.
     */
    readonly id: string;
    /**
     * Section 7.2 project_id FK — never changes (7.4 rule 4).
     */
    readonly project_id: string;
    readonly title: string;
    /**
     * Markdown description (FR-TSK-02).
     */
    readonly description: string;
    readonly acceptance_criteria: Array<string>;
    /**
     * Repo-relative path globs (Section 12.3).
     */
    readonly target_scope: Array<string>;
    readonly test_command: string;
    priority: PriorityEnum;
    /**
     * Canonical G-01 state (ADR-010); draft on create (T1).
     *
     * * `draft` - draft
     * * `pending` - pending
     * * `in_progress` - in_progress
     * * `to_be_audited` - to_be_audited
     * * `in_human_review` - in_human_review
     * * `completed` - completed
     */
    state: StateEnum;
    /**
     * FR-TSK-06: incremented on every change; PATCH echoes it.
     */
    readonly version: number;
    /**
     * Lease holder (WP-1.6).
     */
    readonly worker_agent_id: string | null;
    /**
     * Bridge session (G-18).
     */
    readonly worker_session_id: string | null;
    /**
     * coder | auditor | null.
     */
    readonly claimed_role: string | null;
    readonly lease_acquired_at: string | null;
    readonly lease_expires_at: string | null;
    readonly last_checkpoint_at: string | null;
    readonly failure_retry_count: number;
    readonly attempt_number: number;
    /**
     * Copied from the project policy at creation (Section 7.2).
     */
    readonly audit_required: boolean;
    /**
     * Section 8.4 enum | null.
     */
    readonly review_reason: string | null;
    readonly latest_feedback: string;
    /**
     * none | pending | merging | merged | conflict | failed.
     */
    readonly merge_status: string;
    /**
     * Soft-archive marker; archived tasks stay readable (7.3).
     */
    readonly archived_at: string | null;
    readonly created_by: string | null;
    readonly created_at: string;
    readonly updated_at: string;
    /**
     * Section 7.1 N:N relation (FR-TSK-07): the task ids this task waits on, ordered by id. Server-managed — written through the `depends_on` field of POST/PATCH (replace-the-set), read here.
     */
    readonly depends_on: Array<string>;
};

/**
 * POST /projects/{pid}/tasks body — the FR-TSK-02 create inputs only.
 */
export type TaskCreate = {
    title: string;
    /**
     * Markdown (FR-TSK-02); editable afterwards via PATCH.
     */
    description?: string;
    /**
     * Acceptance-criteria strings (Section 7.2).
     */
    acceptance_criteria?: Array<string>;
    /**
     * Repo-relative globs, validated on creation (Section 12.3).
     */
    target_scope?: Array<string>;
    test_command?: string;
    /**
     * FR-TSK-05; default medium (documented default — not a plan fact).
     *
     * * `urgent` - urgent
     * * `high` - high
     * * `medium` - medium
     * * `low` - low
     */
    priority?: PriorityEnum;
    /**
     * Task ids this task waits on (Section 7.1 relation; FR-TSK-07). Same-project ids only; existence, self and cycles validated — a refusal rolls the whole create back (VALIDATION_ERROR).
     */
    depends_on?: Array<string>;
};

